        m = {"id": len(self.monitors) + 1, "name": name,
              "w": w, "h": h, "dpi": dpi, "hdr": hdr, "vrr": vrr, "refresh": refresh,
              "wallpaper": "Default"}
        self.monitors.append(m)
        return m

