    pygame.draw.rect(surf, (25, 28, 38), rect, border_radius=12)
    surf.blit(font_med.render("🛡 VPN Manager", True, TEXT), (rect.x + 20, rect.y + 15))
    
    # Connection status
    connected = vpn_state['connected']
    status_col = (0, 255, 100) if connected else (255, 100, 100)
