        surf.blit(font_small.render("[L]" if v["encrypted"] else "[O]", True, (20, 20, 30)), (c.x + 16, c.y + 19))
        surf.blit(font_med.render(f"Volume {v['name']}", True, TEXT), (c.x + 52, c.y + 8))
