    ky = rect.y + 160
    surf.blit(font_small.render("Active Keys & Sealed Secrets", True, (255, 200, 100)), (rect.x + 15, ky))
    for i, k in enumerate(tpm_state["keys"]):
        row_y = ky + 22 + i * 22
